1	/**
2	 * pyrepr.mjs — emulation of CPython's `repr()` for the value shapes this port needs.
3	 *
4	 * The reference program prints `print(decoded)`, which renders a `dict` through
5	 * CPython's `dict_repr` -> `PyObject_Repr` on every key/value. Reproducing that
6	 * byte-for-byte means reproducing `unicode_repr()` (Objects/unicodeobject.c) and
7	 * `float_repr` / `long_repr` exactly.
8	 *
9	 * Zero dependencies on purpose: this module imports nothing at all, so it can be
10	 * pulled in from anywhere in the library without risking an import cycle.
11	 */
12	
13	/* ------------------------------------------------------------------ *
14	 * Printability (CPython `Py_UNICODE_ISPRINTABLE`)
15	 * ------------------------------------------------------------------ */
16	
17	/**
18	 * A code point is *non*-printable when its Unicode general category is one of
19	 * Cc, Cf, Cs, Co, Cn, Zl, Zp, Zs. CPython carves out exactly one exception:
20	 * ASCII space U+0020 (a Zs) is considered printable.
21	 *
22	 * The regexp is built once, lazily, and cached. Unicode property escapes are
23	 * available on every modern engine (verified on the Node 18 used here), but if
24	 * a category escape were ever rejected we fall back to a static range table
25	 * instead of throwing while the module is being evaluated.
26	 */
27	const NON_PRINTABLE_PATTERN =
28	  '^[\\p{Cc}\\p{Cf}\\p{Cs}\\p{Co}\\p{Cn}\\p{Zl}\\p{Zp}\\p{Zs}]$';
29	
30	/** @type {RegExp | null} */
31	let nonPrintableRe = null;
32	/** True once we have attempted to build the regexp (successfully or not). */
33	let nonPrintableReReady = false;
34	
35	/**
36	 * Best-effort fallback ranges, used only when Unicode property escapes are
37	 * unavailable. Each entry is an inclusive [start, end] code point range whose
38	 * members are non-printable (ASCII space is filtered out before we get here).
39	 */
40	const FALLBACK_NON_PRINTABLE_RANGES = [
41	  [0x0000, 0x001f], // Cc
42	  [0x007f, 0x00a0], // Cc (DEL, C1 controls) + NBSP (Zs)
43	  [0x00ad, 0x00ad], // SOFT HYPHEN (Cf)
44	  [0x0600, 0x0605], // Cf
45	  [0x061c, 0x061c], // Cf
46	  [0x06dd, 0x06dd], // Cf
47	  [0x070f, 0x070f], // Cf
48	  [0x0890, 0x0891], // Cf
49	  [0x08e2, 0x08e2], // Cf
50	  [0x1680, 0x1680], // OGHAM SPACE MARK (Zs)
51	  [0x180e, 0x180f], // Cf
52	  [0x2000, 0x200f], // Zs + Cf
53	  [0x2028, 0x202f], // Zl, Zp, Cf, Zs
54	  [0x205f, 0x206f], // Zs + Cf (+ unassigned U+2065)
55	  [0x3000, 0x3000], // IDEOGRAPHIC SPACE (Zs)
56	  [0xd800, 0xf8ff], // Cs (surrogates) + Co (BMP private use)
57	  [0xfeff, 0xfeff], // ZERO WIDTH NO-BREAK SPACE (Cf)
58	  [0xfff9, 0xfffb], // Cf
59	  [0x110bd, 0x110bd], // Cf
60	  [0x110cd, 0x110cd], // Cf
61	  [0x13430, 0x1343f], // Cf
62	  [0x1bca0, 0x1bca3], // Cf
63	  [0x1d173, 0x1d17a], // Cf
64	  [0xe0000, 0xe0fff], // Cf (tags) + unassigned
65	  [0xf0000, 0x10ffff], // Co (supplementary private use planes)
66	];
67	
68	/** Build (once) the cached non-printable matcher. */
69	function getNonPrintableRe() {
70	  if (!nonPrintableReReady) {
71	    nonPrintableReReady = true;
72	    try {
73	      nonPrintableRe = new RegExp(NON_PRINTABLE_PATTERN, 'u');
74	    } catch {
75	      // Unicode property escapes unsupported: stay on the range table.
76	      nonPrintableRe = null;
77	    }
78	  }
79	  return nonPrintableRe;
80	}
81	
82	/** Range-table lookup used when no property-escape regexp is available. */
83	function isNonPrintableByRanges(codePoint) {
84	  for (const [start, end] of FALLBACK_NON_PRINTABLE_RANGES) {
85	    if (codePoint >= start && codePoint <= end) return true;
86	  }
87	  return false;
88	}
89	
90	/**
91	 * Printability test for a single code point, expressed as its one-code-point
92	 * string (which is also how lone surrogates reach us).
93	 */
94	function isPrintableChar(ch, codePoint) {
95	  // Fast path for ASCII: printable is exactly U+0020..U+007E.
96	  if (codePoint < 0x80) return codePoint >= 0x20 && codePoint !== 0x7f;
97	  const re = getNonPrintableRe();
98	  if (re !== null) return !re.test(ch);
99	  return !isNonPrintableByRanges(codePoint);
100	}
101	
102	/**
103	 * Python `str.isprintable()`.
104	 *
105	 * Named `codePointString` because `pyReprString` calls it per code point, but it
106	 * accepts any string and mirrors Python's semantics for one: every code point
107	 * must be printable (the empty string is printable).
108	 *
109	 * @param {string} codePointString
110	 * @returns {boolean}
111	 */
112	export function pyIsPrintable(codePointString) {
113	  const s = typeof codePointString === 'string' ? codePointString : String(codePointString);
114	  for (const ch of s) {
115	    const cp = ch.codePointAt(0);
116	    if (!isPrintableChar(ch, cp)) return false;
117	  }
118	  return true;
119	}
120	
121	/* ------------------------------------------------------------------ *
122	 * String repr (CPython `unicode_repr`)
123	 * ------------------------------------------------------------------ */
124	
125	/** Lowercase, zero-padded hex — CPython uses `Py_hexdigits` (lowercase). */
126	function hex(codePoint, width) {
127	  return codePoint.toString(16).padStart(width, '0');
128	}
129	
130	/**
131	 * Python `repr()` of a `str`.
132	 *
133	 * Quote selection follows CPython: single quotes normally; double quotes when
134	 * the string contains a `'` and no `"`; when it contains both, single quotes are
135	 * kept and each `'` is backslash-escaped.
136	 *
137	 * @param {string} str
138	 * @returns {string}
139	 */
140	export function pyReprString(str) {
141	  const s = typeof str === 'string' ? str : String(str);
142	
143	  const hasSingle = s.indexOf("'") !== -1;
144	  const hasDouble = s.indexOf('"') !== -1;
145	  const quote = hasSingle && !hasDouble ? '"' : "'";
146	
147	  let out = quote;
148	  for (const ch of s) {
149	    const cp = ch.codePointAt(0);
150	
151	    // The enclosing quote and the backslash are always escaped.
152	    if (ch === quote || cp === 0x5c) {
153	      out += '\\' + ch;
154	      continue;
155	    }
156	    // Special-cased whitespace escapes.
157	    if (cp === 0x09) {
158	      out += '\\t';
159	      continue;
160	    }
161	    if (cp === 0x0a) {
162	      out += '\\n';
163	      continue;
164	    }
165	    if (cp === 0x0d) {
166	      out += '\\r';
167	      continue;
168	    }
169	    // Non-printable US-ASCII (C0 controls and DEL) -> \xhh.
170	    if (cp < 0x20 || cp === 0x7f) {
171	      out += '\\x' + hex(cp, 2);
172	      continue;
173	    }
174	    // Remaining ASCII is copied verbatim.
175	    if (cp < 0x7f) {
176	      out += ch;
177	      continue;
178	    }
179	    // Non-ASCII: printable code points stay raw, everything else is escaped.
180	    if (isPrintableChar(ch, cp)) {
181	      out += ch;
182	    } else if (cp <= 0xff) {
183	      out += '\\x' + hex(cp, 2);
184	    } else if (cp <= 0xffff) {
185	      out += '\\u' + hex(cp, 4);
186	    } else {
187	      out += '\\U' + hex(cp, 8);
188	    }
189	  }
190	  return out + quote;
191	}
192	
193	/* ------------------------------------------------------------------ *
194	 * Numbers
195	 * ------------------------------------------------------------------ */
196	
197	/** Python `int` repr: plain decimal digits, never exponential. */
198	function pyIntRepr(value) {
199	  // Beyond 1e21 `Number#toString` switches to exponent form; BigInt does not.
200	  if (Number.isFinite(value) && (value >= 1e21 || value <= -1e21)) {
201	    return BigInt(value).toString();
202	  }
203	  return String(value);
204	}
205	
206	/**
207	 * Python `float` repr: shortest string that round-trips, always carrying a `.`
208	 * or an exponent, exponential form when `decpt <= -4 || decpt > 16`, and an
209	 * exponent padded to at least two digits (`1e-05`, not `1e-5`).
210	 */
211	function pyFloatRepr(value) {
212	  if (Number.isNaN(value)) return 'nan';
213	  if (value === Infinity) return 'inf';
214	  if (value === -Infinity) return '-inf';
215	
216	  const negative = value < 0 || Object.is(value, -0);
217	  const sign = negative ? '-' : '';
218	  const magnitude = Math.abs(value);
219	  if (magnitude === 0) return sign + '0.0';
220	
221	  // `toExponential()` with no argument yields the shortest round-tripping
222	  // mantissa, i.e. exactly the digit string CPython's dtoa produces.
223	  const parts = magnitude.toExponential().split('e');
224	  const digits = parts[0].replace('.', '');
225	  const decpt = Number(parts[1]) + 1; // value === 0.<digits> * 10**decpt
226	
227	  if (decpt <= -4 || decpt > 16) {
228	    const exponent = decpt - 1;
229	    const expSign = exponent < 0 ? '-' : '+';
230	    const expDigits = String(Math.abs(exponent)).padStart(2, '0');
231	    const mantissa = digits.length > 1 ? digits[0] + '.' + digits.slice(1) : digits;
232	    return sign + mantissa + 'e' + expSign + expDigits;
233	  }
234	  if (decpt <= 0) {
235	    return sign + '0.' + '0'.repeat(-decpt) + digits;
236	  }
237	  if (decpt >= digits.length) {
238	    return sign + digits + '0'.repeat(decpt - digits.length) + '.0';
239	  }
240	  return sign + digits.slice(0, decpt) + '.' + digits.slice(decpt);
241	}
242	
243	/**
244	 * Recognise a value that has been explicitly tagged as a Python float so that
245	 * `1.0` does not collapse to `1`. Boxed `Number` objects and a handful of
246	 * plain-object tag shapes are accepted; primitives are classified by value.
247	 *
248	 * @returns {{ isFloat: boolean, value: number } | null}
249	 */
250	function unwrapTaggedNumber(value) {
251	  if (value instanceof Number) {
252	    return { isFloat: true, value: value.valueOf() };
253	  }
254	  if (typeof value === 'object' && value !== null) {
255	    const inner = typeof value.value === 'number' ? value.value : null;
256	    if (inner === null) return null;
257	    if (value.__pyFloat === true || value.pyType === 'float' || value.isFloat === true) {
258	      return { isFloat: true, value: inner };
259	    }
260	    if (value.__pyInt === true || value.pyType === 'int' || value.isInteger === true) {
261	      return { isFloat: false, value: inner };
262	    }
263	  }
264	  return null;
265	}
266	
267	/** Untagged numeric primitive: integral values render as `int`, others as `float`. */
268	function pyNumberRepr(value) {
269	  if (Number.isInteger(value) && !Object.is(value, -0)) return pyIntRepr(value);
270	  return pyFloatRepr(value);
271	}
272	
273	/* ------------------------------------------------------------------ *
274	 * Containers
275	 * ------------------------------------------------------------------ */
276	
277	/** Render `[[key, value], ...]` pairs as a Python dict literal. */
278	function pyDictRepr(entries) {
279	  const items = [];
280	  for (const [key, val] of entries) {
281	    items.push(pyRepr(key) + ': ' + pyRepr(val));
282	  }
283	  return '{' + items.join(', ') + '}';
284	}
285	
286	/* ------------------------------------------------------------------ *
287	 * Public entry point
288	 * ------------------------------------------------------------------ */
289	
290	/**
291	 * Python `repr()` for the value shapes produced by this port's JSON parser.
292	 *
293	 * Mappings arrive as `Map` instances (insertion order preserved, which a plain
294	 * JS object would destroy for integer-like keys) and are rendered as dicts.
295	 *
296	 * @param {unknown} value
297	 * @returns {string}
298	 */
299	export function pyRepr(value) {
300	  if (value === null || value === undefined) return 'None';
301	
302	  switch (typeof value) {
303	    case 'boolean':
304	      return value ? 'True' : 'False';
305	    case 'string':
306	      return pyReprString(value);
307	    case 'number':
308	      return pyNumberRepr(value);
309	    case 'bigint':
310	      return value.toString();
311	    default:
312	      break;
313	  }
314	
315	  if (value instanceof Map) return pyDictRepr(value.entries());
316	  if (Array.isArray(value)) return '[' + value.map((item) => pyRepr(item)).join(', ') + ']';
317	
318	  if (value instanceof Set) {
319	    if (value.size === 0) return 'set()';
320	    return '{' + [...value].map((item) => pyRepr(item)).join(', ') + '}';
321	  }
322	
323	  if (value instanceof String) return pyReprString(value.valueOf());
324	  if (value instanceof Boolean) return value.valueOf() ? 'True' : 'False';
325	
326	  const tagged = unwrapTaggedNumber(value);
327	  if (tagged !== null) {
328	    return tagged.isFloat ? pyFloatRepr(tagged.value) : pyIntRepr(tagged.value);
329	  }
330	
331	  if (typeof value === 'object') return pyDictRepr(Object.entries(value));
332	
333	  return String(value);
334	}
