1	/**
2	 * argparse.mjs
3	 *
4	 * A faithful, dependency-free port of the slice of CPython's ``argparse`` that
5	 * test17.py exercises.  The reference binary is a PyInstaller bundle of
6	 * CPython 3.12 (the ``-hx`` short-option-chaining behaviour pins it at
7	 * 3.12.5+), so the algorithms below mirror that exact source revision:
8	 *
9	 *   - ``ArgumentParser._parse_known_args``   (two-pass O/A token classifier)
10	 *   - ``ArgumentParser._parse_optional``     (exact match, "=" form, abbrev)
11	 *   - ``ArgumentParser._get_option_tuples``  (prefix matching / ambiguity)
12	 *   - ``ArgumentParser._match_argument``     (nargs regex, "--" is not a value)
13	 *   - ``ArgumentParser._get_values``         ("--" is stripped for positionals
14	 *                                             only, since 3.12.5)
15	 *   - ``HelpFormatter``                      (usage line + options section)
16	 *
17	 * Everything is written against plain JS strings and arrays; the only import
18	 * is the local Python-repr helper used to quote values inside the
19	 * "invalid choice" diagnostic exactly the way ``%r`` does.
20	 */
21	
22	import { pyReprString } from './pyrepr.mjs';
23	
24	// ---------------------------------------------------------------------------
25	// Constants mirroring argparse's module-level defaults
26	// ---------------------------------------------------------------------------
27	
28	/** ``ArgumentParser(prefix_chars='-')`` — the only prefix we support. */
29	const PREFIX_CHARS = '-';
30	
31	/** ``argparse.SUPPRESS`` — a default of this value keeps a dest out of the namespace. */
32	const SUPPRESS = '==SUPPRESS==';
33	
34	/** ``HelpFormatter(max_help_position=24)``. */
35	const MAX_HELP_POSITION = 24;
36	
37	/**
38	 * ``shutil.get_terminal_size().columns - 2``.  Python falls back to 80 columns
39	 * whenever COLUMNS is unset and stdout is not a terminal, which is how the
40	 * reference binary is measured, so the width is pinned rather than sniffed.
41	 */
42	const HELP_WIDTH = 80 - 2;
43	
44	/** ``ArgumentParser._negative_number_matcher``. */
45	const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;
46	
47	// ---------------------------------------------------------------------------
48	// Internal error type — mirrors argparse.ArgumentError
49	// ---------------------------------------------------------------------------
50	
51	/**
52	 * Raised while parsing; ``parseArgs`` catches it and turns it into the
53	 * standard "argument <name>: <message>" diagnostic.
54	 */
55	class ArgumentError extends Error {
56	  /**
57	   * @param {string|null} argumentName pre-formatted action name ("-h/--help")
58	   * @param {string} message the human readable failure
59	   */
60	  constructor(argumentName, message) {
61	    super(argumentName === null ? message : `argument ${argumentName}: ${message}`);
62	    this.name = 'ArgumentError';
63	    this.argumentName = argumentName;
64	    this.rawMessage = message;
65	  }
66	}
67	
68	// ---------------------------------------------------------------------------
69	// Type converters
70	// ---------------------------------------------------------------------------
71	
72	/** Identity converter — matches ``type=str`` on an already-string argv token. */
73	function strConverter(value) {
74	  return String(value);
75	}
76	strConverter.typeName = 'str';
77	
78	/** ``int(value)`` with argparse's strictness (no partial parses). */
79	function intConverter(value) {
80	  const text = String(value).trim();
81	  if (!/^[+-]?\d+$/.test(text)) {
82	    throw new RangeError('invalid literal');
83	  }
84	  return Number(text);
85	}
86	intConverter.typeName = 'int';
87	
88	/** ``float(value)``. */
89	function floatConverter(value) {
90	  const text = String(value).trim();
91	  if (text === '' || !Number.isFinite(Number(text))) {
92	    throw new RangeError('invalid literal');
93	  }
94	  return Number(text);
95	}
96	floatConverter.typeName = 'float';
97	
98	/**
99	 * Normalises the ``type`` option of addArgument into a callable carrying a
100	 * ``typeName`` used by the "invalid X value" diagnostic.
101	 *
102	 * @param {Function|string|null|undefined} type
103	 * @returns {Function}
104	 */
105	function resolveType(type) {
106	  if (type === null || type === undefined) return strConverter;
107	  if (typeof type === 'function') {
108	    if (type === String) return strConverter;
109	    if (type === Number) return floatConverter;
110	    if (!type.typeName) type.typeName = type.name || 'type';
111	    return type;
112	  }
113	  switch (String(type)) {
114	    case 'str':
115	    case 'string':
116	      return strConverter;
117	    case 'int':
118	      return intConverter;
119	    case 'float':
120	      return floatConverter;
121	    default:
122	      return strConverter;
123	  }
124	}
125	
126	// ---------------------------------------------------------------------------
127	// Action
128	// ---------------------------------------------------------------------------
129	
130	/**
131	 * One registered optional argument.  Only the two actions the script needs
132	 * ('store' and 'help') exist; ``nargs`` is ``null`` for store (exactly one
133	 * value) and ``0`` for help.
134	 */
135	class Action {
136	  constructor({
137	    optionStrings,
138	    dest,
139	    nargs = null,
140	    kind = 'store',
141	    type = null,
142	    required = false,
143	    choices = null,
144	    help = null,
145	    metavar = null,
146	    defaultValue = null,
147	  }) {
148	    this.optionStrings = optionStrings;
149	    this.dest = dest;
150	    this.nargs = nargs;
151	    this.kind = kind;
152	    this.type = resolveType(type);
153	    this.required = required;
154	    this.choices = choices;
155	    this.help = help;
156	    this.metavar = metavar;
157	    this.defaultValue = defaultValue;
158	  }
159	}
160	
161	/**
162	 * ``argparse._get_action_name`` — how an action is named inside error text.
163	 * For optionals it is every option string joined with "/", e.g. "-h/--help".
164	 *
165	 * @param {Action} action
166	 * @returns {string}
167	 */
168	function actionName(action) {
169	  return action.optionStrings.join('/');
170	}
171	
172	// ---------------------------------------------------------------------------
173	// Small text helpers
174	// ---------------------------------------------------------------------------
175	
176	/** Pads ``text`` on the right with spaces until it is ``width`` wide. */
177	function padRight(text, width) {
178	  return text.length >= width ? text : text + ' '.repeat(width - text.length);
179	}
180	
181	/**
182	 * Greedy word wrap, matching ``textwrap.wrap`` closely enough for help text
183	 * (whitespace collapsed, never breaks a long word apart).
184	 *
185	 * @param {string} text
186	 * @param {number} width
187	 * @returns {string[]}
188	 */
189	function wrapText(text, width) {
190	  const words = text.split(/\s+/).filter((word) => word.length > 0);
191	  if (words.length === 0) return [];
192	  const lines = [];
193	  let current = words[0];
194	  for (let i = 1; i < words.length; i += 1) {
195	    const word = words[i];
196	    if (current.length + 1 + word.length <= width) {
197	      current += ` ${word}`;
198	    } else {
199	      lines.push(current);
200	      current = word;
201	    }
202	  }
203	  lines.push(current);
204	  return lines;
205	}
206	
207	// ---------------------------------------------------------------------------
208	// ArgumentParser
209	// ---------------------------------------------------------------------------
210	
211	export class ArgumentParser {
212	  /**
213	   * @param {{prog?: string, addHelp?: boolean, allowAbbrev?: boolean}} [options]
214	   *   ``prog`` defaults to the reference binary's name so every byte written to
215	   *   stdout/stderr matches it.
216	   */
217	  constructor({ prog = 'test17_executable', addHelp = true, allowAbbrev = true } = {}) {
218	    this.prog = prog;
219	    this.allowAbbrev = allowAbbrev;
220	
221	    /** @type {Action[]} registration order drives usage/help/required order */
222	    this._actions = [];
223	    /** @type {Map<string, Action>} insertion-ordered, like Python's dict */
224	    this._optionStringActions = new Map();
225	    /** ``_has_negative_number_optionals`` — true if an option looks like -1 */
226	    this._hasNegativeNumberOptionals = false;
227	
228	    if (addHelp) {
229	      this.addArgument(['-h', '--help'], {
230	        action: 'help',
231	        dest: 'help',
232	        defaultValue: SUPPRESS,
233	        help: 'show this help message and exit',
234	      });
235	    }
236	  }
237	
238	  // -------------------------------------------------------------------------
239	  // Registration
240	  // -------------------------------------------------------------------------
241	
242	  /**
243	   * Registers an optional argument.
244	   *
245	   * @param {string|string[]} optionStrings e.g. '--data' or ['-d', '--data']
246	   * @param {{type?: any, required?: boolean, choices?: any[], help?: string,
247	   *          dest?: string, metavar?: string, action?: string,
248	   *          defaultValue?: any, nargs?: number|null}} [options]
249	   * @returns {Action}
250	   */
251	  addArgument(optionStrings, options = {}) {
252	    const strings = Array.isArray(optionStrings) ? optionStrings.slice() : [optionStrings];
253	    if (strings.length === 0) {
254	      throw new Error('addArgument requires at least one option string');
255	    }
256	    for (const optionString of strings) {
257	      if (!PREFIX_CHARS.includes(optionString.charAt(0))) {
258	        // Positional arguments are intentionally out of scope: the script the
259	        // reference binary was built from declares none.
260	        throw new Error(`positional arguments are not supported: ${optionString}`);
261	      }
262	    }
263	
264	    const {
265	      type = null,
266	      required = false,
267	      choices = null,
268	      help = null,
269	      metavar = null,
270	      action: kind = 'store',
271	      defaultValue = null,
272	      nargs,
273	    } = options;
274	
275	    // ``_get_optional_kwargs``: '--foo-bar' -> 'foo_bar', else '-x' -> 'x'.
276	    let dest = options.dest;
277	    if (dest === undefined || dest === null) {
278	      const longOption = strings.find((s) => s.length > 1 && PREFIX_CHARS.includes(s.charAt(1)));
279	      const source = longOption !== undefined ? longOption : strings[0];
280	      dest = source.replace(/^[-]+/, '').replace(/-/g, '_');
281	    }
282	
283	    const resolvedNargs = nargs !== undefined ? nargs : kind === 'help' ? 0 : null;
284	
285	    const registered = new Action({
286	      optionStrings: strings,
287	      dest,
288	      nargs: resolvedNargs,
289	      kind,
290	      type,
291	      required,
292	      choices,
293	      help,
294	      metavar,
295	      defaultValue,
296	    });
