315	   *
316	   * @param {Action} action
317	   * @returns {string}
318	   */
319	  _metavarFor(action) {
320	    if (action.metavar !== null && action.metavar !== undefined) return action.metavar;
321	    if (action.choices !== null && action.choices !== undefined) {
322	      return `{${action.choices.map((choice) => String(choice)).join(',')}}`;
