340	  /**
341	   * ``HelpFormatter._format_actions_usage`` for a single action: only the first
342	   * option string appears, and non-required actions are bracketed.
343	   *
344	   * @param {Action} action
345	   * @returns {string}
346	   */
347	  _formatUsagePart(action) {
348	    const optionString = action.optionStrings[0];
349	    const part = action.nargs === 0 ? optionString : `${optionString} ${this._metavarFor(action)}`;
350	    return action.required ? part : `[${part}]`;
351	  }
