353	  /**
354	   * @returns {string} "usage: <prog> [-h] --data DATA --verify_iat {true,false}\n"
355	   */
356	  formatUsage() {
357	    const parts = this._actions.map((action) => this._formatUsagePart(action));
358	    const tail = parts.length > 0 ? ` ${parts.join(' ')}` : '';
359	    return `usage: ${this.prog}${tail}\n`;
360	  }
361	
362	  /**
363	   * @returns {string} the full ``--help`` text, terminated by exactly one \n
364	   */
365	  formatHelp() {
366	    // ``HelpFormatter.add_argument`` tracks the widest invocation (+ the 2
367	    // space section indent) to decide where the help column starts.
368	    const indent = 2;
369	    let actionMaxLength = 0;
370	    for (const action of this._actions) {
371	      if (action.help === SUPPRESS) continue;
372	      actionMaxLength = Math.max(
373	        actionMaxLength,
374	        this._formatActionInvocation(action).length + indent,
375	      );
376	    }
377	    const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);
378	    const helpTextWidth = Math.max(HELP_WIDTH - helpPosition, 11);
379	    const actionWidth = helpPosition - indent - 2;
380	
381	    const lines = [];
382	    for (const action of this._actions) {
383	      if (action.help === SUPPRESS) continue;
384	      const invocation = this._formatActionInvocation(action);
385	
386	      if (!action.help) {
387	        // No help text: the line ends right after the invocation, no padding.
388	        lines.push(' '.repeat(indent) + invocation);
389	        continue;
390	      }
391	
392	      const helpLines = wrapText(action.help, helpTextWidth);
393	      if (invocation.length <= actionWidth) {
394	        // Short invocation: help starts on the same line at ``helpPosition``.
395	        const header = ' '.repeat(indent) + padRight(invocation, actionWidth) + '  ';
396	        lines.push(header + (helpLines.length > 0 ? helpLines[0] : ''));
397	        for (let i = 1; i < helpLines.length; i += 1) {
398	          lines.push(' '.repeat(helpPosition) + helpLines[i]);
399	        }
400	      } else {
401	        // Long invocation: it gets its own line, help is indented below it.
402	        lines.push(' '.repeat(indent) + invocation);
403	        for (const helpLine of helpLines) {
404	          lines.push(' '.repeat(helpPosition) + helpLine);
405	        }
406	      }
407	    }
408	
409	    let text = this.formatUsage();
410	    if (lines.length > 0) {
411	      text += `\noptions:\n${lines.join('\n')}\n`;
412	    }
413	    // ``HelpFormatter.format_help`` collapses runs of blank lines and then
414	    // normalises to a single trailing newline.
415	    text = text.replace(/\n\n\n+/g, '\n\n');
416	    return `${text.replace(/^\n+/, '').replace(/\n+$/, '')}\n`;
417	  }
