419	  // -------------------------------------------------------------------------
420	  // Exiting
421	  // -------------------------------------------------------------------------
422	
423	  /** Writes the help text to stdout and exits 0, like argparse's help action. */
424	  exitWithHelp() {
425	    process.stdout.write(this.formatHelp());
426	    process.exit(0);
427	  }
