429	  /**
430	   * ``ArgumentParser.error`` — usage plus "<prog>: error: <message>" on stderr,
431	   * then exit status 2.
432	   *
433	   * @param {string} message
434	   * @returns {never}
435	   */
436	  error(message) {
437	    process.stderr.write(this.formatUsage());
438	    process.stderr.write(`${this.prog}: error: ${message}\n`);
