442	  // -------------------------------------------------------------------------
443	  // Option-string recognition
444	  // -------------------------------------------------------------------------
445	
446	  /**
447	   * ``ArgumentParser._get_option_tuples`` — every registered option string the
448	   * token could be an abbreviation of.
449	   *
450	   * @param {string} optionString
451	   * @returns {Array<[Action, string, string|null, string|null]>}
452	   */
453	  _getOptionTuples(optionString) {
454	    const result = [];
455	    const first = optionString.charAt(0);
456	    const second = optionString.charAt(1);
457	
458	    if (PREFIX_CHARS.includes(first) && PREFIX_CHARS.includes(second)) {
459	      // "--" style: only ever split at the '='.
460	      if (this.allowAbbrev) {
461	        const eq = optionString.indexOf('=');
462	        const optionPrefix = eq === -1 ? optionString : optionString.slice(0, eq);
463	        const sep = eq === -1 ? null : '=';
464	        const explicitArg = eq === -1 ? null : optionString.slice(eq + 1);
465	        for (const [candidate, action] of this._optionStringActions) {
466	          if (candidate.startsWith(optionPrefix)) {
467	            result.push([action, candidate, sep, explicitArg]);
468	          }
469	        }
470	      }
471	    } else if (PREFIX_CHARS.includes(first) && !PREFIX_CHARS.includes(second)) {
472	      // "-x" style: a single-character option may carry its value inline.
473	      const optionPrefix = optionString;
474	      const shortOptionPrefix = optionString.slice(0, 2);
475	      const shortExplicitArg = optionString.slice(2);
476	      for (const [candidate, action] of this._optionStringActions) {
477	        if (candidate === shortOptionPrefix) {
478	          result.push([action, candidate, '', shortExplicitArg]);
479	        } else if (candidate.startsWith(optionPrefix)) {
480	          result.push([action, candidate, null, null]);
481	        }
482	      }
483	    } else {
484	      this.error(`unexpected option string: ${optionString}`);
485	    }
486	
487	    return result;
488	  }
