490	  /**
491	   * ``ArgumentParser._parse_optional`` — decide whether a token is an option.
492	   *
493	   * @param {string} argString
494	   * @returns {[Action|null, string, string|null, string|null]|null}
495	   *   null means "this is a positional-looking token"; a tuple whose first
496	   *   element is null means "an option we do not know about".
497	   */
498	  _parseOptional(argString) {
499	    // An empty string was meant to be a positional.
500	    if (argString === '') return null;
501	
502	    // Anything not starting with a prefix char is a positional.
503	    if (!PREFIX_CHARS.includes(argString.charAt(0))) return null;
504	
505	    // Exact match wins immediately.
506	    if (this._optionStringActions.has(argString)) {
507	      return [this._optionStringActions.get(argString), argString, null, null];
508	    }
509	
510	    // A lone "-" was meant to be positional.
511	    if (argString.length === 1) return null;
512	
513	    // "--opt=value" where the part before "=" is a known option.
514	    const eq = argString.indexOf('=');
515	    if (eq !== -1) {
516	      const optionString = argString.slice(0, eq);
517	      if (this._optionStringActions.has(optionString)) {
518	        return [
519	          this._optionStringActions.get(optionString),
520	          optionString,
521	          '=',
522	          argString.slice(eq + 1),
523	        ];
524	      }
525	    }
526	
527	    // Abbreviations / inline short-option values.
528	    const optionTuples = this._getOptionTuples(argString);
529	    if (optionTuples.length > 1) {
530	      const matches = optionTuples.map((tuple) => tuple[1]).join(', ');
531	      this.error(`ambiguous option: ${argString} could match ${matches}`);
532	    } else if (optionTuples.length === 1) {
533	      return optionTuples[0];
534	    }
535	
536	    // Looks like a negative number and no option string does: positional.
537	    if (NEGATIVE_NUMBER_RE.test(argString) && !this._hasNegativeNumberOptionals) {
538	      return null;
539	    }
540	
541	    // Contains a space: positional.
542	    if (argString.includes(' ')) return null;
543	
544	    // An unknown option string.
545	    return [null, argString, null, null];
546	  }
