548	  // -------------------------------------------------------------------------
549	  // nargs matching
550	  // -------------------------------------------------------------------------
551	
552	  /**
553	   * ``HelpFormatter``-free version of ``_get_nargs_pattern``.  For optionals
554	   * every '-' placeholder is stripped, which is precisely why "--" can never
555	   * be swallowed as an option's value.
556	   *
557	   * @param {Action} action
558	   * @returns {string}
559	   */
560	  _getNargsPattern(action) {
561	    let pattern;
562	    if (action.nargs === null || action.nargs === undefined) {
563	      pattern = '(-*A-*)';
564	    } else {
565	      pattern = `(-*${'A'.repeat(action.nargs).split('').join('-*')}-*)`;
566	    }
567	    if (action.optionStrings.length > 0) {
568	      pattern = pattern.split('-*').join('').split('-').join('');
