573	  /**
574	   * ``ArgumentParser._match_argument`` — how many following tokens this action
575	   * consumes, given the O/A pattern of what comes next.
576	   *
577	   * @param {Action} action
578	   * @param {string} patternString
579	   * @returns {number}
580	   */
581	  _matchArgument(action, patternString) {
582	    const nargsPattern = this._getNargsPattern(action);
583	    const match = new RegExp(`^${nargsPattern}`).exec(patternString);
584	    if (match === null) {
585	      let message;
586	      if (action.nargs === null || action.nargs === undefined) {
587	        message = 'expected one argument';
588	      } else if (action.nargs === 1) {
589	        message = 'expected 1 argument';
590	      } else {
591	        message = `expected ${action.nargs} arguments`;
592	      }
593	      throw new ArgumentError(actionName(action), message);
594	    }
595	    return match[1].length;
596	  }
597	
598	  // -------------------------------------------------------------------------
599	  // Value conversion / validation
600	  // -------------------------------------------------------------------------
601	
602	  /**
603	   * ``ArgumentParser._get_value`` — run the action's type converter.
604	   *
605	   * @param {Action} action
606	   * @param {string} argString
607	   */
608	  _getValue(action, argString) {
609	    try {
610	      return action.type(argString);
611	    } catch (error) {
612	      const typeName = action.type.typeName || 'value';
613	      throw new ArgumentError(
614	        actionName(action),
615	        `invalid ${typeName} value: ${pyReprString(argString)}`,
616	      );
617	    }
618	  }
619	
620	  /**
621	   * ``ArgumentParser._check_value`` — enforce ``choices``.
622	   *
