624	   * @param {*} value
625	   */
626	  _checkValue(action, value) {
627	    if (action.choices !== null && action.choices !== undefined && !action.choices.includes(value)) {
628	      const choices = action.choices.map((choice) => pyReprString(String(choice))).join(', ');
629	      throw new ArgumentError(
630	        actionName(action),
631	        `invalid choice: ${pyReprString(String(value))} (choose from ${choices})`,
632	      );
633	    }
634	  }
