636	  /**
637	   * ``ArgumentParser._get_values``.  Note that since CPython 3.12.5 the leading
638	   * "--" is stripped for positionals only, so ``--data=--`` really does yield
639	   * the string "--".
640	   *
641	   * @param {Action} action
642	   * @param {string[]} argStrings
643	   */
644	  _getValues(action, argStrings) {
645	    if (argStrings.length === 1 && (action.nargs === null || action.nargs === undefined)) {
646	      const value = this._getValue(action, argStrings[0]);
647	      this._checkValue(action, value);
648	      return value;
649	    }
650	    const values = argStrings.map((argString) => this._getValue(action, argString));
651	    for (const value of values) this._checkValue(action, value);
652	    return values;
653	  }
