655	  // -------------------------------------------------------------------------
656	  // Parsing
657	  // -------------------------------------------------------------------------
658	
659	  /**
660	   * Parses argv and returns a namespace object, exiting the process on any
661	   * error exactly the way argparse does.
662	   *
663	   * @param {string[]} [argv] argv without the interpreter and script path
664	   * @returns {Object<string, *>}
665	   */
666	  parseArgs(argv) {
667	    const [namespace, extras] = this.parseKnownArgs(argv);
668	    if (extras.length > 0) {
669	      this.error(`unrecognized arguments: ${extras.join(' ')}`);
670	    }
671	    return namespace;
672	  }
