680	   */
681	  parseKnownArgs(argv) {
682	    const args = argv === undefined || argv === null ? process.argv.slice(2) : argv.slice();
683	    try {
684	      return this._parseKnownArgs(args);
685	    } catch (error) {
686	      if (error instanceof ArgumentError) {
687	        this.error(error.message);
688	      }
689	      throw error;
690	    }
691	  }
692	
693	  /**
694	   * The heart of ``ArgumentParser._parse_known_args``.
695	   *
696	   * @param {string[]} argStrings
697	   * @returns {[Object<string, *>, string[]]}
698	   */
699	  _parseKnownArgs(argStrings) {
700	    // --- namespace defaults -------------------------------------------------
701	    const namespace = {};
702	    for (const action of this._actions) {
703	      if (action.defaultValue !== SUPPRESS) {
704	        namespace[action.dest] = action.defaultValue;
705	      }
706	    }
707	
708	    // --- pass 1: classify every token as an Option or an Argument -----------
709	    // A literal "--" is recorded as '-' and forces everything after it to 'A',
710	    // which is what makes "--data -- x" fail instead of consuming "--".
711	    const pattern = [];
712	    /** @type {Map<number, [Action|null, string, string|null, string|null]>} */
713	    const optionTuples = new Map();
714	    let sawDoubleDash = false;
715	    for (let i = 0; i < argStrings.length; i += 1) {
716	      const argString = argStrings[i];
717	      if (sawDoubleDash) {
718	        pattern.push('A');
719	        continue;
720	      }
721	      if (argString === '--') {
722	        pattern.push('-');
723	        sawDoubleDash = true;
724	        continue;
725	      }
726	      const optionTuple = this._parseOptional(argString);
727	      if (optionTuple === null) {
728	        pattern.push('A');
729	      } else {
730	        optionTuples.set(i, optionTuple);
731	        pattern.push('O');
732	      }
733	    }
734	    const patternString = pattern.join('');
735	
736	    // --- pass 2: consume options left to right ------------------------------
737	    /** @type {string[]} */
738	    const extras = [];
739	    /** @type {Set<Action>} */
740	    const seenActions = new Set();
741	
742	    /**
743	     * ``take_action`` — convert, validate and store one action's values.
744	     *
745	     * @param {Action} action
746	     * @param {string[]} values
747	     * @param {string} optionString
748	     */
749	    const takeAction = (action, values, optionString) => {
750	      seenActions.add(action);
751	      const argumentValues = this._getValues(action, values);
752	      if (action.kind === 'help') {
753	        this.exitWithHelp();
754	        return;
755	      }
756	      namespace[action.dest] = argumentValues;
757	    };
758	
759	    /**
760	     * ``consume_optional`` — handle the option at ``startIndex`` plus whatever
761	     * follows it, returning the index to continue from.
762	     *
763	     * @param {number} startIndex
764	     * @returns {number}
765	     */
766	    const consumeOptional = (startIndex) => {
767	      let [action, optionString, sep, explicitArg] = optionTuples.get(startIndex);
768	      /** @type {Array<[Action, string[], string]>} */
769	      const actionTuples = [];
770	      let stop = startIndex + 1;
771	
772	      for (;;) {
773	        // Unknown option: hand it to the caller as an extra.
774	        if (action === null) {
775	          extras.push(argStrings[startIndex]);
776	          return startIndex + 1;
777	        }
778	
779	        if (explicitArg !== null && explicitArg !== undefined) {
780	          const argCount = this._matchArgument(action, 'A');
781	
782	          // A single-dash zero-arg option may be followed by more options
783	          // packed into the same token ("-hx" behaves like "-h x").
784	          if (
785	            argCount === 0 &&
786	            !PREFIX_CHARS.includes(optionString.charAt(1)) &&
787	            explicitArg !== ''
788	          ) {
789	            if (sep || PREFIX_CHARS.includes(explicitArg.charAt(0))) {
790	              throw new ArgumentError(
791	                actionName(action),
792	                `ignored explicit argument ${pyReprString(explicitArg)}`,
793	              );
794	            }
795	            actionTuples.push([action, [], optionString]);
796	            const char = optionString.charAt(0);
797	            optionString = char + explicitArg.charAt(0);
798	            if (this._optionStringActions.has(optionString)) {
799	              action = this._optionStringActions.get(optionString);
800	              explicitArg = explicitArg.slice(1);
801	              if (explicitArg === '') {
802	                sep = null;
803	                explicitArg = null;
804	              } else if (explicitArg.charAt(0) === '=') {
805	                sep = '=';
806	                explicitArg = explicitArg.slice(1);
807	              } else {
808	                sep = '';
809	              }
810	            } else {
811	              extras.push(char + explicitArg);
812	              stop = startIndex + 1;
813	              break;
814	            }
815	          } else if (argCount === 1) {
816	            stop = startIndex + 1;
817	            actionTuples.push([action, [explicitArg], optionString]);
818	            break;
819	          } else {
820	            throw new ArgumentError(
821	              actionName(action),
822	              `ignored explicit argument ${pyReprString(explicitArg)}`,
823	            );
824	          }
825	        } else {
826	          // No inline value: pull the required count from the following tokens.
827	          const start = startIndex + 1;
828	          const selectedPatterns = patternString.slice(start);
829	          const argCount = this._matchArgument(action, selectedPatterns);
830	          stop = start + argCount;
831	          actionTuples.push([action, argStrings.slice(start, stop), optionString]);
832	          break;
833	        }
834	      }
835	
836	      for (const [tupleAction, tupleArgs, tupleOptionString] of actionTuples) {
837	        takeAction(tupleAction, tupleArgs, tupleOptionString);
838	      }
839	      return stop;
840	    };
841	
842	    // There are no positional actions in this parser, so any token that is not
843	    // consumed by an option — including "--" and everything after it — is an
844	    // extra, collected in argv order.
845	    let index = 0;
846	    while (index < argStrings.length) {
847	      if (optionTuples.has(index)) {
848	        index = consumeOptional(index);
849	      } else {
850	        extras.push(argStrings[index]);
851	        index += 1;
852	      }
853	    }
854	
855	    // --- required arguments are reported before unrecognized ones -----------
856	    const requiredActions = [];
857	    for (const action of this._actions) {
858	      if (!seenActions.has(action) && action.required) {
859	        requiredActions.push(actionName(action));
860	      }
861	    }
862	    if (requiredActions.length > 0) {
863	      this.error(`the following arguments are required: ${requiredActions.join(', ')}`);
864	    }
865	
866	    return [namespace, extras];
867	  }
868	}
