1	/**
2	 * pytime.mjs — Python `time` / `int()` semantics in pure JavaScript.
3	 *
4	 * The original Python script only needs two things from the standard library:
5	 *
6	 *     import time
7	 *     ...
8	 *     "iat": int(time.time())
9	 *
10	 * so this module provides exactly those two primitives (plus a tiny convenience
11	 * wrapper that composes them), with the same edge-case behaviour Python has.
12	 *
13	 * 时间工具：对应原脚本的 `import time`，提供 time.time() 与 int() 的等价实现。
14	 *
15	 * No imports: `Date` and `Math` are ambient globals.
16	 */
17	
18	/** Python raises ValueError for int(nan). */
19	const NAN_ERROR_MESSAGE = 'cannot convert float NaN to integer';
20	
21	/** Python raises OverflowError for int(inf) / int(-inf). */
22	const INFINITY_ERROR_MESSAGE = 'cannot convert float infinity to integer';
23	
24	/**
25	 * Build an Error that carries the name of the Python exception type it mirrors.
26	 *
27	 * Callers (e.g. the claim validators, which in python-jose wrap `int(...)` in
28	 * `try: ... except ValueError:`) can branch on `err.name` instead of parsing
29	 * the message text.
30	 *
31	 * @param {string} name Python exception class name, e.g. 'ValueError'.
32	 * @param {string} message Python's exact message text.
33	 * @returns {Error}
34	 */
35	function pythonError(name, message) {
36	  const err = new Error(message);
37	  err.name = name;
38	  return err;
39	}
40	
41	/**
42	 * Equivalent of Python's `time.time()`.
43	 *
44	 * Returns the number of seconds since the Unix epoch as a float. `Date.now()`
45	 * has millisecond resolution (Python's clock has microsecond resolution), which
46	 * is irrelevant here because the value is immediately truncated to whole
47	 * seconds for the `iat` claim.
48	 *
49	 * 对应 Python 的 time.time()：返回自纪元以来的浮点秒数。
50	 *
51	 * @returns {number} Float seconds since 1970-01-01T00:00:00Z (UTC).
52	 */
53	export function timeTime() {
54	  return Date.now() / 1000;
55	}
56	
57	/**
58	 * Equivalent of Python's builtin `int()` for the value kinds this program can
59	 * encounter: numbers, booleans and decimal strings.
60	 *
61	 * Semantics reproduced:
62	 *   - floats truncate *toward zero*  (int(1.9) === 1, int(-1.9) === -1),
63	 *     which is `Math.trunc`, NOT `Math.floor`;
64	 *   - int(nan)  raises ValueError    -> Error with name 'ValueError';
65	 *   - int(±inf) raises OverflowError -> Error with name 'OverflowError';
66	 *   - int(True) === 1, int(False) === 0 (bool is a subclass of int in Python);
67	 *   - strings are parsed in base 10, allowing surrounding whitespace, an
68	 *     optional sign and PEP 515 underscore digit separators ("1_000" -> 1000);
69	 *     a fractional string such as "1.5" is a ValueError, exactly like Python;
70	 *   - anything else raises TypeError.
71	 *
72	 * 对应 Python 的 int()：向零取整，并复现 NaN / Infinity 的异常行为。
73	 *
74	 * @param {number|boolean|string} value Value to coerce.
75	 * @returns {number} An integral Number.
76	 * @throws {Error} Named 'ValueError', 'OverflowError' or 'TypeError'.
77	 */
78	export function pyInt(value) {
79	  // bool is an int subclass in Python: int(True) == 1.
80	  if (typeof value === 'boolean') {
81	    return value ? 1 : 0;
82	  }
83	
84	  if (typeof value === 'number') {
85	    return truncateNumber(value);
86	  }
87	
88	  if (typeof value === 'string') {
89	    return parseIntegerString(value);
90	  }
91	
92	  throw pythonError(
93	    'TypeError',
94	    `int() argument must be a string, a bytes-like object or a real number, not '${pyTypeName(value)}'`,
95	  );
96	}
97	
98	/**
99	 * Truncate a Number toward zero, rejecting the non-finite values Python
100	 * refuses to convert.
101	 *
102	 * @param {number} value
103	 * @returns {number}
104	 */
105	function truncateNumber(value) {
106	  if (Number.isNaN(value)) {
107	    throw pythonError('ValueError', NAN_ERROR_MESSAGE);
108	  }
109	  if (!Number.isFinite(value)) {
110	    throw pythonError('OverflowError', INFINITY_ERROR_MESSAGE);
111	  }
112	  // Math.trunc drops the fractional part without moving away from zero, and is
113	  // a no-op for values that are already integral (including -0 -> -0, which
114	  // compares equal to 0).
115	  return Math.trunc(value);
116	}
117	
118	/**
119	 * Parse a base-10 integer literal the way Python's `int(str)` does.
120	 *
121	 * @param {string} text
122	 * @returns {number}
123	 */
124	function parseIntegerString(text) {
125	  // Python strips leading/trailing whitespace before parsing; String#trim
126	  // removes the same Unicode whitespace set for every character that can
127	  // realistically appear here.
128	  const trimmed = text.trim();
129	
130	  // ^[+-]?  digits, optionally grouped by single underscores between digits.
131	  const INTEGER_LITERAL = /^[+-]?[0-9]+(?:_[0-9]+)*$/;
132	  if (!INTEGER_LITERAL.test(trimmed)) {
133	    // Python quotes the *original* (untrimmed) string in the message.
134	    throw pythonError('ValueError', `invalid literal for int() with base 10: '${text}'`);
135	  }
136	
137	  const sign = trimmed[0] === '-' ? -1 : 1;
138	  const digits = trimmed.replace(/^[+-]/, '').replace(/_/g, '');
139	  return sign * Number(digits);
140	}
141	
142	/**
143	 * Best-effort Python type name, used only inside TypeError messages.
144	 *
145	 * @param {unknown} value
146	 * @returns {string}
147	 */
148	function pyTypeName(value) {
149	  if (value === null || value === undefined) {
150	    return 'NoneType';
151	  }
152	  if (Array.isArray(value)) {
153	    return 'list';
154	  }
155	  if (value instanceof Map) {
156	    return 'dict';
157	  }
158	  return typeof value;
159	}
160	
161	/**
162	 * `int(time.time())` — the current Unix timestamp in whole seconds, exactly the
163	 * value the reference implementation puts in the `iat` claim.
164	 *
165	 * 对应原脚本的 int(time.time())：当前纪元秒数（向零取整）。
166	 *
167	 * @returns {number} Integral seconds since the epoch.
168	 */
169	export function nowEpochSeconds() {
170	  return pyInt(timeTime());
171	}
