#!/usr/bin/env node
/**
 * test17.mjs — pure-JavaScript port of /workspace/dataset/test17.py.
 *
 * The original script is four statements of real work wrapped in an argparse
 * front end:
 *
 *     import argparse
 *     from jose import jwt
 *     import time
 *     ...
 *     token = jwt.encode(payload, secret)
 *     print(token)
 *     decoded = jwt.decode(token, secret, options=options, algorithms=["HS256"])
 *     print(decoded)
 *
 * This file mirrors it one statement at a time so the two programs can be
 * diffed side by side. Everything the Python version imported from a third
 * party lives under ./lib/ instead:
 *
 *     argparse            -> ./lib/argparse.mjs   (ArgumentParser)
 *     jose.jwt            -> ./lib/jwt.mjs        (encode / decode)
 *     jose.exceptions     -> ./lib/errors.mjs     (JOSEError hierarchy)
 *     time.time / int()   -> ./lib/pytime.mjs     (timeTime / pyInt)
 *     print(dict)         -> ./lib/pyrepr.mjs     (pyRepr)
 *
 * There are no npm packages, no Node builtins and no platform digest helpers
 * anywhere in the tree: SHA-256, the keyed MAC, base64url and UTF-8 are all
 * hand-written in ./lib/, so the program is provably self-contained.
 *
 * Output contract (byte-identical to the reference executable):
 *   line 1  the compact JWS token
 *   line 2  the Python repr() of the decoded claims dict
 *
 * Usage:
 *   node test17.mjs --data <string> --verify_iat {true,false}
 */

import { ArgumentParser } from './lib/argparse.mjs';
import { JOSEError } from './lib/errors.mjs';
import * as jwt from './lib/jwt.mjs';
import { pyRepr } from './lib/pyrepr.mjs';
import { pyInt, timeTime } from './lib/pytime.mjs';

/**
 * `prog` is pinned rather than derived from argv[1] so that usage, help and
 * error text match the reference binary byte for byte no matter how this file
 * is invoked (`node test17.mjs`, `./test17.mjs`, a symlink, ...).
 */
const PROG = 'test17_executable';

/** CPython exits with status 1 when an exception reaches the top level. */
const UNHANDLED_EXCEPTION_STATUS = 1;

/**
 * Build the parser exactly as the Python script does:
 *
 *     parser = argparse.ArgumentParser()
 *     parser.add_argument('--data', type=str, required=True)
 *     parser.add_argument('--verify_iat', type=str, required=True,
 *                         choices=['true', 'false'])
 *
 * `-h/--help` is added implicitly by the constructor, just like argparse's
 * `add_help=True` default.
 *
 * @returns {ArgumentParser}
 */
function buildParser() {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument('--data', { type: 'str', required: true });
  parser.addArgument('--verify_iat', {
    type: 'str',
    required: true,
    choices: ['true', 'false'],
  });
  return parser;
}

/**
 * Render an exception the way the last line of a CPython traceback does:
 * the fully qualified class name, then ": " and `str(exc)` when there is a
 * message. python-jose's exceptions all live in the `jose.exceptions` module,
 * so they are qualified accordingly; anything else (a `ValueError` from
 * `int()`, say) is a builtin and stays bare.
 *
 * @param {unknown} error the thrown value
 * @returns {string} single line, without the trailing newline
 */
function formatPythonException(error) {
  if (!(error instanceof Error)) {
    // Python can raise a non-Exception only via `raise` on a class; treat any
    // stray thrown value as its string form.
    return String(error);
  }
  const qualifiedName =
    error instanceof JOSEError ? `jose.exceptions.${error.name}` : error.name || 'Exception';
  return error.message ? `${qualifiedName}: ${error.message}` : qualifiedName;
}

/**
 * The body of the Python script, statement for statement.
 *
 * Nothing here catches anything: a bad token, a rejected claim or an
 * unsupported algorithm must propagate, exactly as the unguarded Python code
 * would let a `JOSEError` escape.
 */
function main() {
  const parser = buildParser();
  const args = parser.parseArgs(process.argv.slice(2));

  // issued at (iat) claim记录token的发行时间
  const secret = 'secret';
  // A Map, not an object literal: the claim set is serialised in insertion
  // order ({"info":...,"iat":...}) and printed in insertion order, and a plain
  // JS object would silently reorder integer-like keys.
  const payload = new Map([
    ['info', args.data],
    ['iat', pyInt(timeTime())], // int(time.time())
  ]);
  const token = jwt.encode(payload, secret);
  console.log(token);

  // 根据参数决定是否验证iat
  const verifyIat = args.verify_iat === 'true';
  const options = { verify_iat: verifyIat };
  const decoded = jwt.decode(token, secret, { options, algorithms: ['HS256'] });
  console.log(pyRepr(decoded));
}

// ---------------------------------------------------------------------------
// Top-level guard
// ---------------------------------------------------------------------------
//
// argparse failures already exited the process from inside parseArgs (usage +
// diagnostic on stderr, status 2), so anything arriving here is the JS analogue
// of an uncaught Python exception: report it on stderr and finish non-zero.
//
// `process.exitCode` is set instead of calling `process.exit()` so that the
// token printed on stdout before the failure is still flushed when stdout is a
// pipe. A clean run never reaches the catch block and never touches the exit
// code, so success stays success.
try {
  main();
} catch (error) {
  process.stderr.write(`${formatPythonException(error)}\n`);
  process.exitCode = UNHANDLED_EXCEPTION_STATUS;
}

