// SANDBOX-ONLY stub of lib/jws.mjs, written solely to exercise /output/test17.mjs
// end to end while the real module is being authored by another agent.
// Follows the interface in the porting spec. NOT a deliverable.

import { base64UrlEncode, base64UrlDecode } from './base64url.mjs';
import { utf8Encode, concatBytes } from './bytes.mjs';
import { hmacSha256, constantTimeEqual } from './hmac.mjs';
import { JWSAlgorithmError, JWSError, JWSSignatureError } from './errors.mjs';
import { pyJsonDumpsCompact, pyJsonLoads } from './pyjson.mjs';

const ASCII_DOT = '.';

function payloadBytes(payload) {
  if (payload instanceof Uint8Array) return payload;
  if (typeof payload === 'string') return utf8Encode(payload);
  return utf8Encode(pyJsonDumpsCompact(payload));
}

function headerBytes(algorithm, headers) {
  const header = new Map([
    ['alg', algorithm],
    ['typ', 'JWT'],
  ]);
  if (headers) {
    for (const [k, v] of headers instanceof Map ? headers : Object.entries(headers)) {
      header.set(k, v);
    }
  }
  return utf8Encode(pyJsonDumpsCompact(header));
}

function keyBytes(key) {
  return key instanceof Uint8Array ? key : utf8Encode(String(key));
}

export function sign(payload, key, { headers = null, algorithm = 'HS256' } = {}) {
  if (algorithm !== 'HS256') throw new JWSAlgorithmError('Algorithm not supported.');
  const signingInput =
    base64UrlEncode(headerBytes(algorithm, headers)) +
    ASCII_DOT +
    base64UrlEncode(payloadBytes(payload));
  const signature = hmacSha256(keyBytes(key), utf8Encode(signingInput));
  return signingInput + ASCII_DOT + base64UrlEncode(signature);
}

function split(token) {
  const parts = String(token).split(ASCII_DOT);
  if (parts.length !== 3) throw new JWSError('Not enough segments');
  return parts;
}

export function verify(token, key, algorithms, { verify: doVerify = true } = {}) {
  const [encodedHeader, encodedPayload, encodedSignature] = split(token);
  const header = pyJsonLoads(base64UrlDecode(encodedHeader));
  const alg = header instanceof Map ? header.get('alg') : header.alg;
  if (!doVerify) return base64UrlDecode(encodedPayload);
  if (alg !== 'HS256') throw new JWSAlgorithmError('Algorithm not supported.');
  if (algorithms && !algorithms.includes(alg)) {
    throw new JWSError('The specified alg value is not allowed');
  }
  const signingInput = `${encodedHeader}${ASCII_DOT}${encodedPayload}`;
  const expected = hmacSha256(keyBytes(key), utf8Encode(signingInput));
  if (!constantTimeEqual(expected, base64UrlDecode(encodedSignature))) {
    throw new JWSSignatureError('Signature verification failed.');
  }
  return base64UrlDecode(encodedPayload);
}

export function getUnverifiedHeader(token) {
  return pyJsonLoads(base64UrlDecode(split(token)[0]));
}

export function getUnverifiedClaims(token) {
  return base64UrlDecode(split(token)[1]);
}

export { concatBytes };

// SANDBOX-ONLY stub of lib/jwt.mjs, written solely to exercise /output/test17.mjs
// end to end while the real module is being authored by another agent.
// Follows the interface in the porting spec. NOT a deliverable.

import { JWTClaimsError, JWTError } from './errors.mjs';
import { isJsonInteger, pyJsonLoads } from './pyjson.mjs';
import { utf8Decode } from './bytes.mjs';
import * as jws from './jws.mjs';

export const DEFAULT_OPTIONS = {
  verify_signature: true,
  verify_aud: true,
  verify_iat: true,
  verify_exp: true,
  verify_nbf: true,
  verify_iss: true,
  verify_sub: true,
  verify_jti: true,
  verify_at_hash: true,
  require_aud: false,
  require_iat: false,
  require_exp: false,
  require_nbf: false,
  require_iss: false,
  require_sub: false,
  require_jti: false,
  require_at_hash: false,
  leeway: 0,
};

export function encode(claims, key, algorithm = 'HS256', headers = null, accessToken = null) {
  return jws.sign(claims, key, { headers, algorithm });
}

function validateIat(claims) {
  if (!claims.has('iat')) return;
  if (!isJsonInteger(claims.get('iat'))) {
    throw new JWTClaimsError('Issued At claim (iat) must be an integer.');
  }
}

export function decode(token, key, { algorithms = null, options = null } = {}) {
  const merged = { ...DEFAULT_OPTIONS, ...(options || {}) };
  const payload = jws.verify(token, key, algorithms, { verify: merged.verify_signature });
  const claims = pyJsonLoads(utf8Decode(payload));
  if (!(claims instanceof Map)) throw new JWTError('Invalid payload string: must be a json object');
  if (merged.verify_iat) validateIat(claims);
  return claims;
}

